use std::io::*;

const NIL: usize = usize::MAX;

struct N {
    k: i64,
    l: usize,
    r: usize,
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut t: Vec<N> = Vec::new();
    let mut root = NIL;
    let mut out = String::new();
    for line in s.lines() {
        let mut it = line.split_whitespace();
        let c = match it.next() {
            Some(c) => c,
            None => continue,
        };
        let x: i64 = it.next().and_then(|v| v.parse().ok()).unwrap_or(0);
        match c {
            "insert" => {
                let mut cur = root;
                let mut par = NIL;
                let mut left = false;
                let mut dup = false;
                while cur != NIL {
                    if t[cur].k == x {
                        dup = true;
                        break;
                    }
                    par = cur;
                    left = x < t[cur].k;
                    cur = if left { t[cur].l } else { t[cur].r };
                }
                if dup {
                    out.push_str("dup\n");
                } else {
                    t.push(N { k: x, l: NIL, r: NIL });
                    let id = t.len() - 1;
                    if par == NIL {
                        root = id;
                    } else if left {
                        t[par].l = id;
                    } else {
                        t[par].r = id;
                    }
                    out.push_str("ok\n");
                }
            }
            "contains" => {
                let mut cur = root;
                while cur != NIL && t[cur].k != x {
                    cur = if x < t[cur].k { t[cur].l } else { t[cur].r };
                }
                out.push_str(if cur != NIL { "yes\n" } else { "no\n" });
            }
            "delete" => {
                let mut cur = root;
                let mut par = NIL;
                let mut left = false;
                while cur != NIL && t[cur].k != x {
                    par = cur;
                    left = x < t[cur].k;
                    cur = if left { t[cur].l } else { t[cur].r };
                }
                if cur == NIL {
                    out.push_str("missing\n");
                    continue;
                }
                out.push_str("ok\n");
                if t[cur].l != NIL && t[cur].r != NIL {
                    let mut sp = cur;
                    let mut sc = t[cur].r;
                    while t[sc].l != NIL {
                        sp = sc;
                        sc = t[sc].l;
                    }
                    t[cur].k = t[sc].k;
                    let rc = t[sc].r;
                    if sp == cur {
                        t[sp].r = rc;
                    } else {
                        t[sp].l = rc;
                    }
                } else {
                    let ch = if t[cur].l != NIL { t[cur].l } else { t[cur].r };
                    if par == NIL {
                        root = ch;
                    } else if left {
                        t[par].l = ch;
                    } else {
                        t[par].r = ch;
                    }
                }
            }
            "inorder" => {
                if root == NIL {
                    out.push_str("<empty>\n");
                } else {
                    let mut st = Vec::new();
                    let mut cur = root;
                    let mut v = Vec::new();
                    while cur != NIL || !st.is_empty() {
                        while cur != NIL {
                            st.push(cur);
                            cur = t[cur].l;
                        }
                        let n = st.pop().unwrap();
                        v.push(t[n].k.to_string());
                        cur = t[n].r;
                    }
                    out.push_str(&v.join(" "));
                    out.push('\n');
                }
            }
            "height" => {
                let mut best = 0;
                let mut st = Vec::new();
                if root != NIL {
                    st.push((root, 1));
                }
                while let Some((n, d)) = st.pop() {
                    if d > best {
                        best = d;
                    }
                    if t[n].l != NIL {
                        st.push((t[n].l, d + 1));
                    }
                    if t[n].r != NIL {
                        st.push((t[n].r, d + 1));
                    }
                }
                out.push_str(&format!("{}\n", best));
            }
            "min" | "max" => {
                if root == NIL {
                    out.push_str("empty\n");
                } else {
                    let mut cur = root;
                    loop {
                        let nx = if c == "min" { t[cur].l } else { t[cur].r };
                        if nx == NIL {
                            break;
                        }
                        cur = nx;
                    }
                    out.push_str(&format!("{}\n", t[cur].k));
                }
            }
            _ => {}
        }
    }
    print!("{}", out);
}

